      thrombMI: { sex: 'm', story: '\u05e9\u05d7\u05dc\u05d4 \u05d1\u05e7\u05d5\u05d5\u05d0\u05e1\u05d0\u05e7\u05d9 \u05d1\u05e9\u05e0\u05d4 \u05e9\u05e2\u05d1\u05e8\u05d4 \u05d5\u05e0\u05e9\u05d0\u05e8\u05d5 \u05dc\u05d5 \u05de\u05e4\u05e8\u05e6\u05d5\u05ea \u05e2\u05e0\u05e7 \u05d1\u05e2\u05d5\u05e8\u05e7\u05d9\u05dd \u05d4\u05db\u05dc\u05d9\u05dc\u05d9\u05d9\u05dd, \u05de\u05d7\u05d5\u05d5\u05d9\u05e8 \u05e4\u05ea\u05d0\u05d5\u05dd, \u05e6\u05d5\u05e2\u05e7 \u05de\u05db\u05d0\u05d1 \u05d5\u05e7\u05d5\u05e8\u05e1.', clue: '\u05e7\u05d5\u05d5\u05d0\u05e1\u05d0\u05e7\u05d9 \u05d1\u05e9\u05e0\u05d4 \u05e9\u05e2\u05d1\u05e8\u05d4 \u05e2\u05dd \u05de\u05e4\u05e8\u05e6\u05d5\u05ea \u05e2\u05e0\u05e7 \u05d1\u05e2\u05d5\u05e8\u05e7\u05d9\u05dd \u05d4\u05db\u05dc\u05d9\u05dc\u05d9\u05d9\u05dd, \u05de\u05d8\u05d5\u05e4\u05dc \u05d1\u05d0\u05e1\u05e4\u05d9\u05e8\u05d9\u05df \u05d1\u05dc\u05d1\u05d3. \u05db\u05d0\u05d1 \u05e4\u05ea\u05d0\u05d5\u05de\u05d9, \u05d7\u05d9\u05d5\u05d5\u05e8\u05d5\u05df \u05d5\u05d4\u05e7\u05d0\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e7\u05e8\u05d9\u05e1\u05d4; \u05e2\u05dc\u05d9\u05d5\u05ea ST \u05d1-ECG \u05d4\u05d0\u05d7\u05e8\u05d5\u05df.', fix: '\u05d8\u05e4\u05dc\u05d5 \u05d1\u05d6\u05d4 \u05db\u05de\u05d5 \u05d1\u05d0\u05d5\u05d8\u05dd: \u05e7\u05e8\u05d3\u05d9\u05d5\u05dc\u05d5\u05d2\u05d9\u05d4, \u05d5\u05d0\u05d6 \u05e6\u05e0\u05ea\u05d5\u05e8 \u05d0\u05d5 \u05d8\u05e8\u05d5\u05de\u05d1\u05d5\u05dc\u05d9\u05d6\u05d4; \u05e9\u05e7\u05dc\u05d5 ECMO.' },
      trauma: { sex: 'm', story: '\u05e0\u05e4\u05d2\u05e2 \u05de\u05de\u05db\u05d5\u05e0\u05d9\u05ea \u05d1\u05d6\u05de\u05df \u05e9\u05e8\u05db\u05d1 \u05e2\u05dc \u05d0\u05d5\u05e4\u05e0\u05d9\u05d9\u05dd.', clue: '\u05e0\u05e4\u05d2\u05e2 \u05de\u05de\u05db\u05d5\u05e0\u05d9\u05ea \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea. \u05e9\u05d8\u05e4\u05d9 \u05d3\u05dd \u05e2\u05dc \u05d4\u05d1\u05d8\u05df \u05d5\u05d4\u05d0\u05d2\u05df, \u05d9\u05e8\u05da \u05e0\u05e4\u05d5\u05d7\u05d4, \u05d5\u05e8\u05d9\u05d3\u05d9 \u05e6\u05d5\u05d5\u05d0\u05e8 \u05e9\u05d8\u05d5\u05d7\u05d9\u05dd, \u05db\u05e0\u05d9\u05e1\u05ea \u05d0\u05d5\u05d5\u05d9\u05e8 \u05e9\u05d5\u05d5\u05d4 \u05d1\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd.', fix: '\u05e2\u05e6\u05e8\u05d5 \u05d0\u05ea \u05d4\u05d3\u05d9\u05de\u05d5\u05dd \u05d5\u05d4\u05d7\u05d6\u05d9\u05e8\u05d5 \u05e0\u05e4\u05d7: \u05d3\u05dd \u05de\u05d5\u05e7\u05d3\u05dd, \u05d7\u05d2\u05d5\u05e8\u05ea \u05d0\u05d2\u05df, \u05db\u05d9\u05e8\u05d5\u05e8\u05d2 \u05d8\u05e8\u05d0\u05d5\u05de\u05d4; \u05e0\u05e7\u05d6\u05d5 \u05d0\u05ea \u05d4\u05d7\u05d6\u05d4 \u05d0\u05dd \u05d9\u05e9 \u05d7\u05e9\u05d3 \u05dc\u05d7\u05d6\u05d4 \u05d0\u05d5\u05d5\u05d9\u05e8 \u05d1\u05dc\u05d7\u05e5.' }
